-- 012_soa_test_evaluation_referencia_implementacion.sql
--
-- Complementa 011_soa_test_evaluation_iso27001_nov2025.sql: carga la columna "Referencia
-- de la implementación del control" del mismo Excel (SoA_V01), que se había omitido en
-- 011. No hay una columna dedicada para esto en MAE_CONTROL_EVALUATION -- se usa
-- C_IMPROVEMENT_ACTIONS (quedó vacía en 011, el Excel no trae "acciones de mejora" real).
--
-- Los saltos de línea del Excel (varias referencias por celda) se normalizan a " | " para
-- que quede en una sola línea legible. 6 de las 93 filas superan los 500 caracteres del
-- varchar y quedan recortadas con "…" al final -- son referencias con muchos documentos
-- de sustento listados, no pérdida de información crítica.
--
-- Depende de que 011 ya se haya corrido (la evaluación "Evaluación - Noviembre 2025 (SoA
-- data de prueba)" debe existir). Igual que 011, no asume un id fijo de evaluación.
--
-- Probado en DB de desarrollo (Railway). Pendiente de aplicar en producción (junto con 011).

BEGIN;

DO $$
DECLARE
  v_evaluation_id integer;
BEGIN
  SELECT "N_EVALUATION_ID_PK" INTO v_evaluation_id
  FROM "MAE_EVALUATION"
  WHERE "C_DESCRIPTION" = 'Evaluación - Noviembre 2025 (SoA data de prueba)' AND "N_STANDARD_ID_FK" = 4
  ORDER BY "N_EVALUATION_ID_PK" DESC LIMIT 1;

  IF v_evaluation_id IS NULL THEN
    RAISE EXCEPTION 'No se encontró la evaluación de 011_soa_test_evaluation_iso27001_nov2025.sql -- correr ese script primero.';
  END IF;

  UPDATE "MAE_CONTROL_EVALUATION" SET "C_IMPROVEMENT_ACTIONS" = 'Políticas de SI, establecidas en la Directiva DI04-GPP/GC Directrices de Seguridad de la Información, aprobada por Resolución Jefatural n° 00157-2024-JN/ONPE (20/09/2024) y publicada en Plataforma Digital Única del Estado Peruano, (www.gob.pe/onpe) y en el Portal de Transparencia de la ONPE, asi como por Comunicaciones Onpe.' WHERE "N_EVALUATION_ID_FK" = v_evaluation_id AND "N_CONTROL_ID_FK" = 2; -- 5.1
  UPDATE "MAE_CONTROL_EVALUATION" SET "C_IMPROVEMENT_ACTIONS" = 'Roles y responsabilidades establecidas en Directiva DI04-GPP/GC Directrices de Seguridad de la Información (numeral 6.1.2). | Se  conformó el Comité de Gobierno y Transformación Digital (CGTD) mediante la R.J.N° 000179-2024-JN/ONPE (17/10/2024)' WHERE "N_EVALUATION_ID_FK" = v_evaluation_id AND "N_CONTROL_ID_FK" = 3; -- 5.2
  UPDATE "MAE_CONTROL_EVALUATION" SET "C_IMPROVEMENT_ACTIONS" = 'Se ha segredo las funciones en el documento Texto integrado del reglamento de organización y funciones de la oficina nacional de procesos electorales, aprobado por RJ N° 000125-2024-JN/ONPE (27/06/2024)' WHERE "N_EVALUATION_ID_FK" = v_evaluation_id AND "N_CONTROL_ID_FK" = 4; -- 5.3
  UPDATE "MAE_CONTROL_EVALUATION" SET "C_IMPROVEMENT_ACTIONS" = 'Directiva DI04-GPP/GC Directrices de Seguridad de la Información, aprobada por RJ N° 004912-2022-JN/ONPE (02/12/2022) | Politica del Sistema Integrado de Gestión, aprobada por RJ N° 004912-2022-JN/ONPE (02/12/2022)  | Se  conformó el Comité de Gobierno y Transformación Digital (CGTD) mediante la R.J.N° 000179-2024-JN/ONPE (17/10/2024)' WHERE "N_EVALUATION_ID_FK" = v_evaluation_id AND "N_CONTROL_ID_FK" = 5; -- 5.4
  UPDATE "MAE_CONTROL_EVALUATION" SET "C_IMPROVEMENT_ACTIONS" = 'OD11-GPP/GC:Comunicaciones internas y externas del SGSI' WHERE "N_EVALUATION_ID_FK" = v_evaluation_id AND "N_CONTROL_ID_FK" = 7; -- 5.5
  UPDATE "MAE_CONTROL_EVALUATION" SET "C_IMPROVEMENT_ACTIONS" = 'DI04-GPP/GC: Directrices de seguridad de la información (numeral 6.1.6) | Registro de contactos con los fabricantes de soluciones de seguridad de TI. | Registro de participación en eventos organizados por el CNSD. | Comunicados de seguridad digital por parte del Centro Nacional de Seguridad Digital al OSCD  | Registro de participación en grupo de CISOs creado por la PCM | OD11-GPP/GC:Comunicaciones internas y externas del SGSI' WHERE "N_EVALUATION_ID_FK" = v_evaluation_id AND "N_CONTROL_ID_FK" = 8; -- 5.6
  UPDATE "MAE_CONTROL_EVALUATION" SET "C_IMPROVEMENT_ACTIONS" = '_Comunicados de alertas de seguridad por el CNSD: Alerta integrada de seguridad digital (https://www.gob.pe/institucion/pcm/colecciones/791-alerta-integrada-de-seguridad-digital-del-cnsd) | _Servicio de Ethical Hacking' WHERE "N_EVALUATION_ID_FK" = v_evaluation_id AND "N_CONTROL_ID_FK" = 9; -- 5.7
  UPDATE "MAE_CONTROL_EVALUATION" SET "C_IMPROVEMENT_ACTIONS" = 'DI04: Directrices de seguridad de la información(numeral 6.1.8). | PR12-GITE/TI Gestión de requerimiento y desarrollo de SW institucional. | PR05-GPP/GC: Gestión de Riesgos' WHERE "N_EVALUATION_ID_FK" = v_evaluation_id AND "N_CONTROL_ID_FK" = 10; -- 5.8
  UPDATE "MAE_CONTROL_EVALUATION" SET "C_IMPROVEMENT_ACTIONS" = 'FM13-GPP/GC: Inventario de activos de información' WHERE "N_EVALUATION_ID_FK" = v_evaluation_id AND "N_CONTROL_ID_FK" = 11; -- 5.9
  UPDATE "MAE_CONTROL_EVALUATION" SET "C_IMPROVEMENT_ACTIONS" = 'DI04-GPP/GC: Directrices de seguridad de la información (numeral 6.1.10) | FM30-GRH/RRHH: Acuerdo de confidencialidad | DI06-GITE/TI: Uso y conservación de equipos de computo y periféricos. | _DI04-GITE-TI Servicio de correo electrónico institucional | _DI03-GITE-TI El buen uso del servicio de internet' WHERE "N_EVALUATION_ID_FK" = v_evaluation_id AND "N_CONTROL_ID_FK" = 12; -- 5.10
