  UPDATE "MAE_CONTROL_EVALUATION" SET "C_IMPROVEMENT_ACTIONS" = 'DI04-GPP/GC: Directrices de seguridad de la información (Numeral 6.1.12) | FM13-GPP/GC: Inventario de activos de información | DI02-SG_TD Atención de las solicitudes de acceso a la información pública en la ONPE. | _RJ N° 000086-J/ONPE Delegación de la clasificación de información' WHERE "N_EVALUATION_ID_FK" = v_evaluation_id AND "N_CONTROL_ID_FK" = 14; -- 5.12
