  UPDATE "MAE_CONTROL_EVALUATION" SET "C_IMPROVEMENT_ACTIONS" = 'DI04-GPP/GC: Directrices de seguridad de la información (Numeral 6.1.18) | DI05-GITE/TI: Control de acceso a estaciones de trabajo' WHERE "N_EVALUATION_ID_FK" = v_evaluation_id AND "N_CONTROL_ID_FK" = 20; -- 5.18
  UPDATE "MAE_CONTROL_EVALUATION" SET "C_IMPROVEMENT_ACTIONS" = '- DI04-GPP/GC: Directrices de seguridad de la información (Numeral 6.1.19) |  -  Requisitos de SI en el FM24-GAD_LOG Términos de Referencia (SERVICIO) para procedimiento de selección |  - FM27-GAD_LOG Términos de referencia (servicio) para contrataciones menores a 8 UIT  |  - Ley de contrataciones |  - Expediente de contratación | _PR01-GAD/LOG Realización de contratos menores' WHERE "N_EVALUATION_ID_FK" = v_evaluation_id AND "N_CONTROL_ID_FK" = 21; -- 5.19
  UPDATE "MAE_CONTROL_EVALUATION" SET "C_IMPROVEMENT_ACTIONS" = '- DI04-GPP/GC: Directrices de seguridad de la información (Numeral 6.1.19) |  -  Requisitos de SI en el FM24-GAD_LOG Términos de Referencia (SERVICIO) para procedimiento de selección |  - FM27-GAD_LOG Términos de referencia (servicio) para contrataciones menores a 8 UIT  |  - Aplicación de la Ley de contrataciones |  - Registro de expedientes de contratación' WHERE "N_EVALUATION_ID_FK" = v_evaluation_id AND "N_CONTROL_ID_FK" = 22; -- 5.20
