  UPDATE "MAE_CONTROL_EVALUATION" SET "C_IMPROVEMENT_ACTIONS" = 'DI04-GPP/GC: Directrices de seguridad de la información (Numeral 6.4.32). |  _Aislamiento de entornos de producción durante auditoría.' WHERE "N_EVALUATION_ID_FK" = v_evaluation_id AND "N_CONTROL_ID_FK" = 93; -- 8.34
END $$;

COMMIT;

-- Verificación post-ejecución: debe dar 93 (todas con referencia cargada)
SELECT count(*) as con_referencia
FROM "MAE_CONTROL_EVALUATION" ce
JOIN "MAE_EVALUATION" e ON e."N_EVALUATION_ID_PK" = ce."N_EVALUATION_ID_FK"
WHERE e."C_DESCRIPTION" = 'Evaluación - Noviembre 2025 (SoA data de prueba)' AND e."N_STANDARD_ID_FK" = 4
  AND ce."C_IMPROVEMENT_ACTIONS" IS NOT NULL AND ce."C_IMPROVEMENT_ACTIONS" != '';
